def solution(friends, gifts):
    answer = []

    # 각 친구의 선물 개수 초기화
    friend_gift_counts = {friend: [0, 0] for friend in friends}

    # 기존에 주고받은 선물 기록 처리
    for gift in gifts:
        sender, receiver = gift.split()

        if sender != receiver:
            friend_gift_counts[sender][0] += 1
            friend_gift_counts[receiver][1] += 1

    # 현재 점수 계산
    scores = {}
    for friend, counts in friend_gift_counts.items():
        score = counts[0] - counts[1]
        scores[friend] = score

    # 최대값 찾기
    max_score = max(scores.values())
    result_friends = []

    for friend, score in scores.items():
        if score == max_score:
            result_friends.append(friend)

    return len(result_friends)

