def solution(diffs, times, limit):
    answer = 0

    for i in range(len(times)):
        if diffs[i] <= limit:
            answer += times[i]
        else:
            count = (diffs[i] - limit) // times[i]

            # 남은 시간으로 퍼즐을 풀 수 있는가?
            left_time = limit * count - times[i] * count
            additional_time = 0

            while left_time < times[i]:
                additional_time += times[i] + times[0]
                left_time += times[i]

            answer += times[i] + additional_time

    return answer

